'use strict';
const $=id=>document.getElementById(id);
let workflow='RLHF',running=false,logOffset=0,pollTimer=null;
const plans={RLHF:[['SFT','instruction'],['Reward Model','preference'],['PPO','prompts']],SFT:[['SFT','instruction']],DPO:[['DPO','preference']]};
const dataDefaults={sft:{id:'HuggingFaceH4/ultrachat_200k',split:'train_sft'},preference:{id:'HuggingFaceH4/ultrafeedback_binarized',split:'train_prefs'},prompts:{id:'HuggingFaceH4/ultrachat_200k',split:'train_gen'}};
function roles(){return workflow==='SFT'?[['sft','SFT / instruction']]:workflow==='DPO'?[['preference','Preference / chosen + rejected']]:[['sft','SFT / instruction'],['preference','Reward Model / preference'],['prompts','PPO / prompts']];}
function renderDatasets(){const root=$('demo-datasets');root.innerHTML=roles().map(([key,label])=>{const d=dataDefaults[key];return `<div class="dataset-row"><b>${label}</b><input data-dataset="${key}" data-field="id" value="${d.id}"><select data-dataset="${key}" data-field="type"><option value="huggingface">HF</option><option value="json">JSON</option></select><input data-dataset="${key}" data-field="split" value="${d.split}"><span></span></div>`;}).join('');root.querySelectorAll('[data-field="type"]').forEach(select=>select.addEventListener('change',()=>{const row=select.closest('.dataset-row');row.querySelector('[data-field="id"]').placeholder=select.value==='json'?'/path/to/data.json':'Hugging Face dataset ID';showPreview();}));}
function renderPlan(){const rows=plans[workflow];$('plan-title').textContent=`console_${workflow.toLowerCase()}`;$('demo-plan').innerHTML=rows.map((r,i)=>`<div class="stage"><span>0${i+1}</span><b>${r[0]}</b><small>${r[1]}</small></div>`).join('');}
function readDatasets(){const output={};document.querySelectorAll('#demo-datasets [data-field="id"]').forEach(input=>{const row=input.closest('.dataset-row');output[input.dataset.dataset]={type:row.querySelector('[data-field="type"]').value,id:input.value,split:row.querySelector('[data-field="split"]').value};});return output;}
function buildPayload(){return {workflow,model_source:'local',model:$('demo-model').value.trim(),gpus:[...document.querySelectorAll('#demo-gpus input:checked')].map(x=>Number(x.value)),output_root:'outputs/console',max_steps:Number($('demo-steps').value),batch_size:Number($('demo-batch').value),learning_rate:Number($('demo-learning-rate').value),max_length:Number($('demo-max-length').value),beta:Number($('demo-beta').value),ppo_episodes:Number($('demo-ppo-episodes').value),response_length:Number($('demo-response-length').value),lora:$('demo-lora').checked,datasets:readDatasets()};}
function showPreview(){const data=buildPayload();$('demo-json').textContent=JSON.stringify(data,null,2);$('metric-gpu').textContent=data.gpus.length?data.gpus.join(','):'—';}
function setView(view){const guide=view==='guide';$('guide-view').classList.toggle('hidden',!guide);$('console-view').classList.toggle('hidden',guide);$('view-title').textContent=guide?'指南':'实验控制';document.querySelectorAll('.workspace').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function setStatus(status,detail=''){running=status==='running';$('status-label').textContent=status.toUpperCase();$('log-status').textContent=status.toUpperCase();$('demo-run').disabled=running;$('demo-validate').disabled=running;$('demo-stop').disabled=!running;if(detail)$('log-status').title=detail;}
function appendLog(lines){if(!lines?.length)return;const log=$('demo-log');if(log.textContent.includes('启动训练后'))log.textContent='';log.textContent+=`${lines.join('\n')}\n`;log.scrollTop=log.scrollHeight;}
async function refreshStatus(){try{const status=await fetch('api/train/status').then(r=>r.json());setStatus(status.status,status.return_code===null||status.return_code===undefined?'':`return code ${status.return_code}`);if(status.id)$('log-status').textContent=status.status.toUpperCase();const logs=await fetch(`api/train/logs?offset=${logOffset}`).then(r=>r.json());appendLog(logs.lines);logOffset=logs.next_offset;if(status.status==='running')$('metric-stage').textContent='running';else if(status.status==='succeeded'){$('metric-stage').textContent='saved';$('metric-progress').textContent='100%';}else if(status.status==='failed')$('metric-stage').textContent='failed';}catch(error){setStatus('failed',error.message);}}
async function validate(){const response=await fetch('api/train/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(buildPayload())});const body=await response.json();if(!response.ok)throw Error(body.error||'配置校验失败');appendLog([`✓ config validated · stages: ${body.stages.join(' → ')}`]);}
async function start(){logOffset=0;$('demo-log').textContent='';$('metric-progress').textContent='0%';try{const response=await fetch('api/train/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(buildPayload())});const body=await response.json();if(!response.ok)throw Error(body.error||'启动失败');setStatus('running');appendLog([`$ local training job ${body.id}`,`$ CUDA_VISIBLE_DEVICES=${body.gpus?.join(',')||'<default>'}`]);}catch(error){setStatus('failed',error.message);appendLog([`✕ ${error.message}`]);}}
async function stop(){await fetch('api/train/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await refreshStatus();}
async function loadGpus(){try{const list=await fetch('api/gpus').then(r=>r.json());const selected=list.length?list[0].index:4;$('demo-gpus').innerHTML=(list.length?list:[{index:4,name:'GPU 4',memory_free_mb:0,utilization_gpu:0},{index:5,name:'GPU 5',memory_free_mb:0,utilization_gpu:0},{index:6,name:'GPU 6',memory_free_mb:0,utilization_gpu:0}]).map((g,i)=>`<label><input type="checkbox" value="${g.index}" ${g.index===selected?'checked':''}> GPU ${g.index}</label>`).join('');$('demo-gpus').querySelectorAll('input').forEach(x=>x.addEventListener('change',showPreview));showPreview();}catch{}}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));document.querySelectorAll('[data-switch]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.switch)));document.querySelectorAll('[data-workflow]').forEach(b=>b.addEventListener('click',()=>{workflow=b.dataset.workflow;document.querySelectorAll('[data-workflow]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-method]').forEach(group=>group.classList.toggle('hidden',group.dataset.method!==workflow));renderDatasets();renderPlan();showPreview();}));document.querySelectorAll('[data-method]').forEach(group=>group.classList.toggle('hidden',group.dataset.method!==workflow));document.addEventListener('input',showPreview);document.addEventListener('change',showPreview);$('demo-validate').addEventListener('click',async()=>{try{await validate();}catch(e){appendLog([`✕ ${e.message}`]);}});$('demo-run').addEventListener('click',start);$('demo-stop').addEventListener('click',stop);$('demo-copy').addEventListener('click',()=>navigator.clipboard?.writeText($('demo-json').textContent));setView('guide');renderDatasets();renderPlan();loadGpus();showPreview();refreshStatus();pollTimer=setInterval(refreshStatus,1200);
